import{useEffect,useMemo,useRef,useState}from'react';import{Link,useLocation,useNavigate}from'react-router-dom';import{motion,AnimatePresence}from'framer-motion';import{ArrowDown,ArrowLeft,ArrowRight,ArrowUpRight,BookOpen,Check,ChevronDown,Code2,Command,ExternalLink,Feather,Filter,FolderGit2,Hash,Home,LayoutDashboard,ArrowUp,Library,Menu,Moon,Play,Plus,Search,Settings,Sun,Tag,X,Clock3,CalendarDays,MoreHorizontal,Trash2,Edit3,Eye,LogOut,Upload,Image as ImageIcon,PanelLeftClose,MoveRight,Bookmark,Flame,Dot,Activity,CheckCircle2}from'lucide-react';import{initialNotes,initialPosts,initialProjects,initialSeries,initialVideos,type Post}from'./data';import{firebaseEnabled}from'./firebase';
